from itertools import product
from playwright.sync_api import sync_playwright
import tkinter as tk

def fetch_dominosa(url="https://www.puzzle-dominosa.com/"):
    """
    输入 puzzle-dominosa 网页链接（支持每日、每周、每月等任意尺寸页面），
    后台静默抓取并直接返回 (height, width, grid)
    """
    print(f"正在后台启动无头浏览器抓取 Dominosa 页面: {url} ...")
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        page = browser.new_page()
        page.goto(url, wait_until="networkidle")

        # 核心等待：等棋盘所有格子渲染就位
        page.wait_for_selector("#game .cell", timeout=15000)

        # 将经过实战验证的绝对坐标归一化脚本注入后台浏览器
        result = page.evaluate("""() => {
            // 1. 获取所有绝对定位的格子
            let cells = Array.from(document.querySelectorAll('#game .cell'));
            if (cells.length === 0) {
                cells = Array.from(document.querySelectorAll(
                    '#puzzleContainer .cell, [id*="puzzle"] .cell, .board-back ~ div[class*="cell"]'
                ));
            }

            // 2. 提取坐标与数值
            const extracted = cells.map(c => {
                const span = c.querySelector('span');
                let val = span ? parseInt(span.textContent.trim(), 10) : NaN;
                if (isNaN(val)) {
                    const m = c.className.match(/cell(\\d+)/);
                    if (m) val = parseInt(m[1], 10);
                }
                return {
                    top: parseInt(c.style.top, 10),
                    left: parseInt(c.style.left, 10),
                    val: val
                };
            }).filter(d => !isNaN(d.val) && !isNaN(d.top) && !isNaN(d.left));

            if (extracted.length === 0) {
                return { error: "未找到任何格子，请检查页面是否已加载完毕。" };
            }

            // 3. 根据 top / left 的最小正差值，动态计算每格宽高
            const uniqSort = arr => [...new Set(arr)].sort((a, b) => a - b);
            const tops = uniqSort(extracted.map(d => d.top));
            const lefts = uniqSort(extracted.map(d => d.left));

            let cellH = 0, cellW = 0;
            for (let i = 1; i < tops.length; i++) {
                const diff = tops[i] - tops[i - 1];
                if (diff > 0) { cellH = diff; break; }
            }
            for (let i = 1; i < lefts.length; i++) {
                const diff = lefts[i] - lefts[i - 1];
                if (diff > 0) { cellW = diff; break; }
            }
            if (!cellH || !cellW) {
                const inner = cells[0] ? cells[0].querySelector('div') : null;
                if (inner) {
                    if (!cellH) cellH = parseInt(inner.style.height, 10) || 22;
                    if (!cellW) cellW = parseInt(inner.style.width, 10) || 22;
                }
                if (!cellH) cellH = 22;
                if (!cellW) cellW = 22;
            }

            // 4. 计算行列数并填装二维数组
            const rows = Math.round(Math.max(...extracted.map(d => d.top)) / cellH) + 1;
            const cols = Math.round(Math.max(...extracted.map(d => d.left)) / cellW) + 1;

            const grid = Array.from({length: rows}, () => Array(cols).fill(0));
            extracted.forEach(d => {
                const r = Math.round(d.top / cellH);
                const c = Math.round(d.left / cellW);
                if (r >= 0 && r < rows && c >= 0 && c < cols) grid[r][c] = d.val;
            });

            return { height: rows, width: cols, grid: grid };
        }""")

        browser.close()

        if result.get("error"):
            raise RuntimeError(result["error"])

        print(f"✔ 抓取成功！识别尺寸: {result['height']} 行 x {result['width']} 列")
        return result["height"], result["width"], result["grid"]


def visualize_puzzle(width, height, grid, bigdict, yesdict):
    """
    数邻 (Dominosa) 高保真可视化 (全面适配 yesdict 架构)
    - grid: 二维数字矩阵
    - bigdict: 坐标 -> 骨牌编号 (未结合为 -1)
    - yesdict: 坐标 -> 允许连通的活人邻居集合 set([(r,c), ...])
    """
    root = tk.Tk()
    root.title(f"Dominosa Visualizer ({width}x{height})")

    # 根据尺寸自适应格子大小 (26x27 时约 28px)
    max_dim = max(height, width)
    cell_size = max(16, min(36, 820 // max_dim))

    canvas_w = width * cell_size
    canvas_h = height * cell_size

    canvas = tk.Canvas(root, width=canvas_w, height=canvas_h, bg="#FFFFFF")
    canvas.pack(padx=15, pady=15)

    font_size = max(7, int(cell_size * 0.42))
    num_font = ("Consolas", font_size, "bold")

    # 多米诺骨牌柔和交替底色池
    PALETTE = ["#E8F4F8", "#FCE8E6", "#E6F4EA", "#FDF7E2", "#F3E8FD", "#FCEFE6"]

    # 1. 绘制格子底色与数字
    for r in range(height):
        for c in range(width):
            x1 = c * cell_size
            y1 = r * cell_size
            x2 = x1 + cell_size
            y2 = y1 + cell_size

            oid = bigdict.get((r, c), -1)
            # 已结合的骨牌涂上浅淡底色，未结合的为纯白
            bg = PALETTE[oid % len(PALETTE)] if oid != -1 else "#FAFAFA"
            canvas.create_rectangle(x1, y1, x2, y2, fill=bg, outline="#E8E8E8", width=1)

            val = grid[r][c]
            txt_color = "#111111" if oid != -1 else "#888888"
            canvas.create_text(x1 + cell_size / 2, y1 + cell_size / 2, text=str(val), fill=txt_color, font=num_font)

    # 2. 根据 yesdict 绘制【被切断的鲜红阻断线】
    # 只要邻居不在 yesdict 集合里，说明此路已被斩断！
    for r in range(height):
        for c in range(width):
            curr = (r, c)
            curr_can_reach = yesdict.get(curr, set())
            x1 = c * cell_size
            y1 = r * cell_size
            x2 = x1 + cell_size
            y2 = y1 + cell_size

            # 检查右侧邻居 (r, c+1)
            if c < width - 1:
                right_neighbor = (r, c + 1)
                if right_neighbor not in curr_can_reach:
                    # 斩断！画一条鲜红的断路墙！
                    canvas.create_line(x2, y1, x2, y2, fill="#E53935", width=2.5)

            # 检查下方邻居 (r+1, c)
            if r < height - 1:
                down_neighbor = (r + 1, c)
                if down_neighbor not in curr_can_reach:
                    # 斩断！画一条鲜红的断路墙！
                    canvas.create_line(x1, y2, x2, y2, fill="#E53935", width=2.5)

    # 3. 绘制已确立多米诺的【加粗纯黑外框】（将两格圈成一块完整骨牌！）
    for r in range(height):
        for c in range(width):
            curr = (r, c)
            oid = bigdict.get(curr, -1)
            if oid == -1:
                continue

            x1 = c * cell_size
            y1 = r * cell_size
            x2 = x1 + cell_size
            y2 = y1 + cell_size

            # 如果上/下/左/右不是同一个多米诺，就画加粗实线
            if r == 0 or bigdict.get((r - 1, c), -1) != oid:
                canvas.create_line(x1, y1, x2, y1, fill="#1A1A1A", width=3)
            if r == height - 1 or bigdict.get((r + 1, c), -1) != oid:
                canvas.create_line(x1, y2, x2, y2, fill="#1A1A1A", width=3)
            if c == 0 or bigdict.get((r, c - 1), -1) != oid:
                canvas.create_line(x1, y1, x1, y2, fill="#1A1A1A", width=3)
            if c == width - 1 or bigdict.get((r, c + 1), -1) != oid:
                canvas.create_line(x2, y1, x2, y2, fill="#1A1A1A", width=3)

    # 外围总框
    canvas.create_rectangle(1, 1, canvas_w, canvas_h, outline="#1A1A1A", width=3)
    root.mainloop()


def number_1(i,j,i1,j1):#弱化封装，返回二者的数字组合
    if bigdict[(i,j)]+bigdict[(i1,j1)]>-2:#至少一个已经有主了
        return#使用“卫语句”，扁平化提高可读性
    a=grid[i][j]
    b=grid[i1][j1]
    if a>b:
        a,b=b,a
    return (a,b)

def number(i,j,i1,j1):#更改temdict
    loc=number_1(i,j,i1,j1)
    if not loc is None:
        if temdict[loc]==0:
            temdict[loc]=[((i,j),(i1,j1))]
        elif type(temdict[loc])==list:
            temdict[loc].append(((i,j),(i1,j1)))

def effect(loc1,loc2,com):#结算，顺便玩effect梗
    global order
    comdict[com]=True
    #把对应格子周围标为不可行
    for s in (loc1,loc2):
        bigdict[s]=order
        #留着yesdict当猎杀名单
        for ne in yesdict[s]:
            yesdict[ne].discard(s)
    yesdict[loc1]={loc2} #防止周围来沾边；最后再改回True用于可视化
    yesdict[loc2]={loc1}
    order+=1
    #让对应数字组合的组合不可行
    for i, j in product(range(height), range(width)):#扫描每个格子周围
        if i<height-1:
            combine=number_1(i,j,i+1,j)
            if combine==com:
                yesdict[(i,j)].discard((i+1,j))
                yesdict[(i+1,j)].discard((i,j))
        if j<width-1:
            combine=number_1(i,j,i,j+1)
            if combine==com:
                yesdict[(i,j)].discard((i,j+1))
                yesdict[(i,j+1)].discard((i,j))

