height, width, grid = fetch_dominosa('https://cn.puzzle-dominosa.com/?size=10')


#数字范围：0~height-1，共height个数字

bigdict={}#键为坐标
for i, j in product(range(height), range(width)):
    bigdict[(i,j)]=-1#-1代表未结合；结合后按顺序赋值


yesdict={}#键为坐标，值为可通行格子
for i, j in product(range(height), range(width)):
    yesdict[(i,j)]=set()
    for di,dj in ((0,-1),(0,1),(-1,0),(1,0)):
        if 0<=i+di<height and 0<=j+dj<width:
            yesdict[(i,j)].add((i+di,j+dj))


comdict={}#键为数字组合
for i, j in product(range(height), range(height)):
        if i<=j:
            comdict[(i,j)]=False#还未占有

comdict_n1={}#键为数字组合
for i, j in product(range(height), range(height)):
        if i<=j:
            comdict_n1[(i,j)]=False#还未占有

comdict_n2={}#键为数字组合
for i, j in product(range(height), range(height)):
        if i<=j:
            comdict_n2[(i,j)]=False#还未占有

order=0
progress=0
for i in yesdict:
    progress+=len(yesdict[i])
last_progress=height*width*4
while last_progress>progress:#现在最小进展变成了yesdict减少；所以考察progress的单调减少
    print(progress)
    last_progress=progress
    #DE1.0：若全场只有这里有这个组合，组上
    temdict={}#键为数字组合
    for i, j in product(range(height), range(height)):
        if i<=j:
            if comdict[(i,j)]:#已经有了就直接判死刑
                temdict[(i,j)]=-1
            else:
                temdict[(i,j)]=0 #故技重施！0代表没找到（不可能）；列表代表所有；-1则是已有
    for i, j in product(range(height), range(width)):#扫描每个格子周围
        if i<height-1:
            number(i,j,i+1,j)  
        if j<width-1:
            number(i,j,i,j+1)
            
    for i in temdict:
        if temdict[i]==0:
            print(f'出错！{i}组合未出现！')
        if type(temdict[i])==list and len(temdict[i])==1:#找到！两个格子坐标是temdict[i][0][0]和temdict[i][0][1]；数字组合是i
            effect(temdict[i][0][0],temdict[i][0][1],i)
    #DE1.0：“生命会自己找到出路”：若这个格子四周只有一处能走，往这边走
    for i in yesdict:
        if bigdict[i]==-1:
            if not yesdict[i]:
                print(f'出错！{i}格子没有出路！')
            elif len(yesdict[i])==1:#找到！两个格子坐标是i和j，数字组合是com
                j=next(iter(yesdict[i]))
                com=number_1(i[0],i[1],j[0],j[1])
                effect(i,j,com)
    #DE2.0：单数强迫
    for i in yesdict:
        if bigdict[i]==-1 and len(yesdict[i])>1:
            n=set()
            for j in yesdict[i]:
                n.add(grid[j[0]][j[1]])
            if len(n)==1:
                com=(grid[i[0]][i[1]],next(iter(n))) if grid[i[0]][i[1]]<=next(iter(n)) else (next(iter(n)),grid[i[0]][i[1]])
                if comdict_n1[com]==False:
                    #print(f'{i}只有{n}这一个数字！')
                    comdict_n1[com]=True
                    #让对应数字组合的组合不可行
                    for y, x in product(range(height), range(width)):#扫描每个格子周围
                        if y<height-1:
                            combine=number_1(y,x,y+1,x)
                            if combine==com and (y,x)!=i and (y+1,x)!=i:
                                yesdict[(y,x)].discard((y+1,x))
                                yesdict[(y+1,x)].discard((y,x))
                        if x<width-1:
                            combine=number_1(y,x,y,x+1)
                            if combine==com and (y,x)!=i and (y,x+1)!=i:
                                yesdict[(y,x)].discard((y,x+1))
                                yesdict[(y,x+1)].discard((y,x))
    #DE2.0：单组合强迫
    #刷新temdict
    temdict={}#键为数字组合
    for i, j in product(range(height), range(height)):
        if i<=j:
            if comdict[(i,j)]:#已经有了就直接判死刑
                temdict[(i,j)]=-1
            else:
                temdict[(i,j)]=0 #故技重施！0代表没找到（不可能）；列表代表所有；-1则是已有
    for i, j in product(range(height), range(width)):#扫描每个格子周围
        if i<height-1:
            number(i,j,i+1,j)  
        if j<width-1:
            number(i,j,i,j+1)

    for i in temdict:
        if type(temdict[i])==list and len(temdict[i])<=4 and comdict_n2[i]==False:
            check={temdict[i][0][0],temdict[i][0][1]}
            for j in temdict[i][1:]:
                check1={j[0],j[1]}
                check=check & check1
            if len(check)==1:
                comdict_n2[i]=True
                center = next(iter(check))
                #print(i,center)#i指数字组合，center是中心方格坐标
                kill=[]
                for k in yesdict[center]:
                    com=number_1(center[0],center[1],k[0],k[1])
                    if com!=i:
                        kill.append(k) 
                for k in kill:
                    yesdict[center].discard(k)
                    yesdict[k].discard(center)


    progress=0
    for i in yesdict:
        progress+=len(yesdict[i])

visualize_puzzle(width, height, grid, bigdict, yesdict)
